// Service Worker — Cuaderno de entreno
const CACHE = 'entreno-v12';
const PRECACHE = ['./', './index.html', './manifest.json', './apple-touch-icon.png'];

// Iconos incrustados como base64 (no necesita carpeta icons/ en GitHub)
const ICONS = {
  'apple-touch-icon.png': '',
  'icon-192.png': '',
  'icon-512.png': ''
};

function iconResponse(b64) {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return new Response(buf, { status: 200, headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public,max-age=86400' } });
}

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  // Servir iconos desde base64 integrado
  const iconName = Object.keys(ICONS).find(n => url.pathname.endsWith(n));
  if (iconName) { e.respondWith(iconResponse(ICONS[iconName])); return; }
  // Firebase y externos: network-first
  if (url.hostname.includes('firebase') || url.hostname.includes('googleapis') ||
      url.hostname.includes('youtube') || url.hostname.includes('fonts')) {
    e.respondWith(fetch(e.request).catch(() => caches.match(e.request)));
    return;
  }
  // Resto: cache-first
  e.respondWith(
    caches.match(e.request).then(cached => {
      if (cached) return cached;
      return fetch(e.request).then(res => {
        if (res.ok) { const cl = res.clone(); caches.open(CACHE).then(c => c.put(e.request, cl)); }
        return res;
      });
    })
  );
});
